pub type NonEmpty = Str
  invariant: this.len() > 0;

fn greet(name: &NonEmpty) -> Unit {
  io.println("Hello, " + name + "!");
}

fn main() -> Int {
  let username: NonEmpty = "Kilo";
  greet(&username);
  return 0;
}
